def transform(grid):
    # Compare how much each non-divider color's occurrence count increases
    # below the horizontal separator versus above it; output the winning color.
    divider = next(i for i, row in enumerate(grid) if row and all(v == row[0] for v in row) and row[0] != 0)
    colors = sorted({v for row in grid for v in row if v not in (0, grid[divider][0])})
    upper = {c: sum(v == c for row in grid[:divider] for v in row) for c in colors}
    lower = {c: sum(v == c for row in grid[divider + 1:] for v in row) for c in colors}
    chosen = max(colors, key=lambda c: lower[c] - upper[c])
    return [[chosen, chosen], [chosen, chosen]]

